class Solution { fun shortestCommonSupersequence(str1:String,str2:String):String{val m=str1.length;val n=str2.length;val dp=Array(m+1){IntArray(n+1)};for(i in m-1 downTo 0)for(j in n-1 downTo 0)dp[i][j]=if(str1[i]==str2[j])dp[i+1][j+1]+1 else maxOf(dp[i+1][j],dp[i][j+1]);val answer=StringBuilder();var i=0;var j=0;while(i<m&&j<n)if(str1[i]==str2[j]){answer.append(str1[i++]);j++}else if(dp[i+1][j]>=dp[i][j+1])answer.append(str1[i++]) else answer.append(str2[j++]);answer.append(str1.substring(i));answer.append(str2.substring(j));return answer.toString()} }
